157:   public static void start(EventLoop eventLoop, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
158:     ChainIndex index = new ChainIndex(handlers, registry, true);
159:     requestConstants.indexes.push(index);
160: 
161:     DefaultContext context = new DefaultContext(requestConstants);
162:     requestConstants.context = context;
163: 
164:     context.pathBindings = new PathBindingStorage(new RootPathBinding(requestConstants.request.getPath()));
