234:   public void next() {
235:     Handler handler = null;
236: 
237:     ChainIndex index = requestConstants.indexes.peek();
238:     while (handler == null) {
239:       if (index.hasNext()) {
240:         handler = index.next();
241:         if (handler.getClass().equals(ChainHandler.class)) {
242:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getCurrentRegistry(), false));
243:           index = requestConstants.indexes.peek();
244:           handler = null;
245:         }
246:       } else if (index.first) {
247:         handler = requestConstants.applicationConstants.end;
248:       } else {
249:         requestConstants.indexes.pop();
250:         index = requestConstants.indexes.peek();
251:       }
252:     }
