254:     try {
255:       requestConstants.handler = handler;
256:       handler.handle(this);
257:     } catch (Throwable e) {
258:       if (e instanceof HandlerException) {
259:         throw (HandlerException) e;
260:       } else {
261:         throw new HandlerException(e);
262:       }
263:     }
